package com.agacostays.billing.consumer;import com.agacostays.billing.service.BillingService;import com.fasterxml.jackson.databind.*;import org.springframework.kafka.annotation.KafkaListener;import org.springframework.stereotype.Component;import java.math.BigDecimal;@Component public class FoodDeliveredEventConsumer{private final BillingService s;private final ObjectMapper m;public FoodDeliveredEventConsumer(BillingService s,ObjectMapper m){this.s=s;this.m=m;}@KafkaListener(topics="food.delivered",groupId="billing-service-food")public void consume(String msg){try{JsonNode n=m.readTree(msg);if(n.hasNonNull("bookingId")&&n.hasNonNull("orderId"))s.addRestaurantCharge(n.get("bookingId").asLong(),n.get("orderId").asLong(),n.hasNonNull("amount")?new BigDecimal(n.get("amount").asText()):BigDecimal.ZERO);}catch(Exception ignored){}}}
